    const rendered = renderAriaTreeAsJSON(ariaSnapshot, options);
    this._lastAriaSnapshotForQuery = ariaSnapshot;
    return { json: rendered.json, iframeRefs: ariaSnapshot.iframeRefs, iframeDepths: rendered.iframeDepths };
